const char SH_MODPROG_EP_GLSL[] =
    "// The sRGB curve DOOM Eternal's uberparticles applies to both texture channels (2016's SRGBlinearApprox).\n"
    "float ep_lin(float x) { return x * (x * (x * 0.305306011 + 0.682171111) + 0.012522878); }\n"
    "\n"
    "// The inverse of DOOM 2016's SRGBlinear (global.inc: x / 12.92 up to 0.04045, else pow(x / 1.055 + 0.0521327, 2.4)),\n"
    "// which its particle vertex stage applies to the vertex colour; and the alpha floor its CPU remaps the alpha past\n"
    "// (r_particlesMinAlpha, default 16 of 255).\n"
    "float ep_srgb(float x) { return x <= 0.0031308 ? x * 12.92 : 1.055 * (pow(x, 1.0 / 2.4) - 0.0521327); }\n"
    "const float EP_MIN_ALPHA = 16.0 / 255.0;\n"
    "\n"
    "// A bicubic B-spline sample of the light atlas (four bilinear taps), as both games read it.\n"
    "float ep_w0(float a) { return (1.0 / 6.0) * (a * (a * (-a + 3.0) - 3.0) + 1.0); }\n"
    "float ep_w1(float a) { return (1.0 / 6.0) * (a * a * (3.0 * a - 6.0) + 4.0); }\n"
    "float ep_w2(float a) { return (1.0 / 6.0) * (a * (a * (-3.0 * a + 3.0) + 3.0) + 1.0); }\n"
    "float ep_w3(float a) { return (1.0 / 6.0) * (a * a * a); }\n"
    "vec3 ep_bicubic(sampler2D image, vec2 uv, vec2 res)\n"
    "{\n"
    "    uv = uv * res + 0.5;\n"
    "    vec2 iuv = floor(uv), fuv = fract(uv);\n"
    "    float g0x = ep_w0(fuv.x) + ep_w1(fuv.x), g1x = ep_w2(fuv.x) + ep_w3(fuv.x);\n"
    "    float g0y = ep_w0(fuv.y) + ep_w1(fuv.y), g1y = ep_w2(fuv.y) + ep_w3(fuv.y);\n"
    "    float h0x = -1.0 + ep_w1(fuv.x) / g0x, h1x = 1.0 + ep_w3(fuv.x) / g1x;\n"
    "    float h0y = -1.0 + ep_w1(fuv.y) / g0y, h1y = 1.0 + ep_w3(fuv.y) / g1y;\n"
    "    vec3 t0 = textureLod(image, (vec2(iuv.x + h0x, iuv.y + h0y) - 0.5) / res, 0.0).xyz;\n"
    "    vec3 t1 = textureLod(image, (vec2(iuv.x + h1x, iuv.y + h0y) - 0.5) / res, 0.0).xyz;\n"
    "    vec3 t2 = textureLod(image, (vec2(iuv.x + h0x, iuv.y + h1y) - 0.5) / res, 0.0).xyz;\n"
    "    vec3 t3 = textureLod(image, (vec2(iuv.x + h1x, iuv.y + h1y) - 0.5) / res, 0.0).xyz;\n"
    "    return g0y * (g0x * t0 + g1x * t1) + g1y * (g0x * t2 + g1x * t3);\n"
    "}\n"
    "\n"
    "// V: 0 colour, 1 texcoord0 (current and next frame uv), 2 texcoord1 (x 1 + 10 gp0, z frame blend, w gp3),\n"
    "//    3 texcoord2 (xyz world position), 4 texcoord4 (xy light atlas uv, z 1 + 10 gp1), 5 texcoord6 (fog), 6 the\n"
    "//    fragment position\n"
    "// P: 0 eternalparticle (x mode: 0 unlit, 1 lit, 4 explosion (a liquid stage\n"
    "//    keeps the game's own blood shading: its material names liquidhighq, not this program); y emissiveMultiplier; z the emissive mask's\n"
    "//    multiplier; w depthOffsetScale, units), 1 eternalparticlefade (x near fade begin, y near fade end, z the soft\n"
    "//    distance, units; w 1 when the stage has an emissive mask sheet), 2 eternalparticlecolor (the emissive mask\n"
    "//    colour, or the explosion's gradient2), 3 eternalparticlecolor2 (rgb the explosion's gradient3; w a lit stage's scale, 1 for a CPU stage:\n"
    "//    a NEW-system stage Eternal lights per vertex draws (L + k)(1 + k)), 4 projectionmatrixz,\n"
    "//    5 globalvieworigin\n"
    "// U: 0 renderpositiontoviewtexture, 1 particleatlasparms, 2 foglightinscattercolor, 3 foglightinscatterintensity,\n"
    "//    4 foglightoppositecolor, 5 fogcolor, 6 transparencylightmult\n"
    "void ep_shade(inout vec4 frag, vec4 V[7], vec4 P[6], vec4 U[7])\n"
    "{\n"
    "    vec4 cur = texture(samp_transmap, V[1].xy);\n"
    "    vec4 nxt = texture(samp_transmap, V[1].zw);\n"
    "    float fb = V[2].z;\n"
    "    float R = mix(ep_lin(cur.r), ep_lin(nxt.r), fb);\n"
    "    float G = mix(ep_lin(cur.g), ep_lin(nxt.g), fb);\n"
    "    if (G < 1e-6) discard;\n"
    "    float mode = P[0].x;\n"
    "    float gp0 = (V[2].x - 1.0) / 10.0;\n"
    "    float gp1 = (V[4].z - 1.0) / 10.0;\n"
    "    float gp3 = V[2].w;\n"
    "    vec3 c = vec3(ep_srgb(V[0].r), ep_srgb(V[0].g), ep_srgb(V[0].b));\n"
    "\n"
    "    // near fade, on the distance from the view\n"
    "    float ca = ep_srgb(V[0].a) * (1.0 - EP_MIN_ALPHA) + EP_MIN_ALPHA;\n"
    "    if (P[1].x > P[1].y) {\n"
    "        float d = length(V[3].xyz - P[5].xyz);\n"
    "        ca *= clamp((d - P[1].y) / (P[1].x - P[1].y), 0.0, 1.0);\n"
    "    }\n"
    "    // soft particle, on linear view depth\n"
    "    vec2 tc = V[6].xy * U[0].zw + U[0].xy;\n"
    "    float zs = P[4].w / (textureLod(samp_viewdepthmap, tc, 0.0).x + P[4].z);\n"
    "    float zf = P[4].w / (V[6].z + P[4].z);\n"
    "    float soft = clamp((zs - zf - clamp(1.0 - G, 0.0, 1.0) * P[0].w) / max(P[1].z, 1e-3), 0.0, 1.0);\n"
    "\n"
    "    float m = 1.0;\n"
    "    if (P[1].w != 0.0) m = mix(texture(samp_eternalparticleemissivemap, V[1].xy).r, texture(samp_eternalparticleemissivemap, V[1].zw).r, fb);\n"
    "\n"
    "    vec3 rgb;\n"
    "    float a;\n"
    "    float curve = mix(sqrt(G), G, gp3);\n"
    "    if (mode == 1.0) {\n"
    "        vec3 L = ep_bicubic(samp_particleslightatlasmap, V[4].xy, U[1].xy);\n"
    "        rgb = R * c * (L + 200.0 * gp0) * P[3].w;\n"
    "        if (P[0].z != 0.0) rgb += P[2].rgb * P[0].z * m * m;\n"
    "        a = curve * ca * (1.0 + 10.0 * gp1);\n"
    "    } else if (mode == 4.0) {\n"
    "        vec3 L = ep_bicubic(samp_particleslightatlasmap, V[4].xy, U[1].xy);\n"
    "        rgb = mix(L * R * c, mix(P[2].rgb, P[3].rgb, m) * P[0].y, m);\n"
    "        float o = curve * ca;\n"
    "        a = mix(sqrt(o), o, gp3) * ca;\n"
    "    } else {\n"
    "        rgb = R * c * (1.0 + 200.0 * gp0) * P[0].y * ca * ca;\n"
    "        a = curve * ca * (1.0 + 10.0 * gp1);\n"
    "    }\n"
    "    a = clamp(a * soft, 0.0, 1.0);\n"
    "\n"
    "    // 2016's fog (the stock program's, from its fog interpolator)\n"
    "    vec3 heightFog = mix(U[2].xyz * U[3].x, U[4].xyz, V[5].z);\n"
    "    float fogAmount = clamp(V[5].y + V[5].x, 0.0, 1.0);\n"
    "    float fogSafe = max(fogAmount, 0.0001);\n"
    "    vec3 fogColor = mix(U[5].xyz, heightFog, max(0.0, (fogSafe - V[5].x) / fogSafe));\n"
    "    rgb = mix(fogColor * U[6].x, rgb, 1.0 - fogAmount);\n"
    "\n"
    "    frag = vec4(rgb * a, a);\n"
    "}\n"
;

const char SH_MODPROG_EP_DECL[] =
    "\t\t// eternalparticles.decl.inc -- DOOM Eternal's particle shading of the product's particle program (modprog.h) in\n"
    "\t\t// the render program language, for the OpenGL renderer, which compiles a program from its decl text. modprog.c\n"
    "\t\t// inserts this text after the base fragment stage's includes and ETERNAL_PARTICLE( result ) after its\n"
    "\t\t// PREMULTIPLY_ALPHA_BLENDED( result ). The same function, line for line, as ep_shade in eternalparticles.frag\n"
    "\t\t// (the Vulkan module): see there for DOOM Eternal's rule. The engine compiles a program's fragment text inside\n"
    "\t\t// main(), so the helpers are macros and templates, never functions.\n"
    "\t\t#define epLin( x ) ( ( x ) * ( ( x ) * ( ( x ) * 0.305306011 + 0.682171111 ) + 0.012522878 ) )\n"
    "\t\t#define epSrgb( x ) ( ( x ) <= 0.0031308 ? ( x ) * 12.92 : 1.055 * ( pow( ( x ), 1.0 / 2.4 ) - 0.0521327 ) )\n"
    "\t\t#define EP_MIN_ALPHA ( 16.0 / 255.0 )\n"
    "\t\t#define epW0( a ) ( ( 1.0 / 6.0 ) * ( ( a ) * ( ( a ) * ( -( a ) + 3.0 ) - 3.0 ) + 1.0 ) )\n"
    "\t\t#define epW1( a ) ( ( 1.0 / 6.0 ) * ( ( a ) * ( a ) * ( 3.0 * ( a ) - 6.0 ) + 4.0 ) )\n"
    "\t\t#define epW2( a ) ( ( 1.0 / 6.0 ) * ( ( a ) * ( ( a ) * ( -3.0 * ( a ) + 3.0 ) + 3.0 ) + 1.0 ) )\n"
    "\t\t#define epW3( a ) ( ( 1.0 / 6.0 ) * ( ( a ) * ( a ) * ( a ) ) )\n"
    "\t\t#template EP_BICUBIC( dst, image, uv0, res ) {\n"
    "\t\t\tfloat2 epUv = ( uv0 ) * ( res ) + 0.5;\n"
    "\t\t\tfloat2 epIuv = floor( epUv );\n"
    "\t\t\tfloat2 epFuv = frac( epUv );\n"
    "\t\t\tfloat epG0x = epW0( epFuv.x ) + epW1( epFuv.x );\n"
    "\t\t\tfloat epG1x = epW2( epFuv.x ) + epW3( epFuv.x );\n"
    "\t\t\tfloat epG0y = epW0( epFuv.y ) + epW1( epFuv.y );\n"
    "\t\t\tfloat epG1y = epW2( epFuv.y ) + epW3( epFuv.y );\n"
    "\t\t\tfloat epH0x = -1.0 + epW1( epFuv.x ) / epG0x;\n"
    "\t\t\tfloat epH1x = 1.0 + epW3( epFuv.x ) / epG1x;\n"
    "\t\t\tfloat epH0y = -1.0 + epW1( epFuv.y ) / epG0y;\n"
    "\t\t\tfloat epH1y = 1.0 + epW3( epFuv.y ) / epG1y;\n"
    "\t\t\tfloat3 epT0 = tex2Dlod( image, float4( ( float2( epIuv.x + epH0x, epIuv.y + epH0y ) - 0.5 ) / ( res ), 0.0, 0.0 ) ).xyz;\n"
    "\t\t\tfloat3 epT1 = tex2Dlod( image, float4( ( float2( epIuv.x + epH1x, epIuv.y + epH0y ) - 0.5 ) / ( res ), 0.0, 0.0 ) ).xyz;\n"
    "\t\t\tfloat3 epT2 = tex2Dlod( image, float4( ( float2( epIuv.x + epH0x, epIuv.y + epH1y ) - 0.5 ) / ( res ), 0.0, 0.0 ) ).xyz;\n"
    "\t\t\tfloat3 epT3 = tex2Dlod( image, float4( ( float2( epIuv.x + epH1x, epIuv.y + epH1y ) - 0.5 ) / ( res ), 0.0, 0.0 ) ).xyz;\n"
    "\t\t\tdst = epG0y * ( epG0x * epT0 + epG1x * epT1 ) + epG1y * ( epG0x * epT2 + epG1x * epT3 );\n"
    "\t\t}\n"
    "\t\t#endtemplate\n"
    "\n"
    "\t\t#template ETERNAL_PARTICLE( epResult ) {\n"
    "\t\t\tfloat4 epCur = tex2D( $transMap, fragment.texcoord0.xy );\n"
    "\t\t\tfloat4 epNxt = tex2D( $transMap, fragment.texcoord0.zw );\n"
    "\t\t\tfloat epFb = fragment.texcoord1.z;\n"
    "\t\t\tfloat epR = lerp( epLin( epCur.x ), epLin( epNxt.x ), epFb );\n"
    "\t\t\tfloat epG = lerp( epLin( epCur.y ), epLin( epNxt.y ), epFb );\n"
    "\t\t\tclip( epG - 1e-6 );\n"
    "\t\t\tfloat epMode = $eternalParticle.x;\n"
    "\t\t\tfloat epGp0 = ( fragment.texcoord1.x - 1.0 ) / 10.0;\n"
    "\t\t\tfloat epGp1 = ( fragment.texcoord4.z - 1.0 ) / 10.0;\n"
    "\t\t\tfloat epGp3 = fragment.texcoord1.w;\n"
    "\t\t\tfloat3 epC = float3( epSrgb( fragment.color.x ), epSrgb( fragment.color.y ), epSrgb( fragment.color.z ) );\n"
    "\n"
    "\t\t\tfloat epCa = epSrgb( fragment.color.w ) * ( 1.0 - EP_MIN_ALPHA ) + EP_MIN_ALPHA;\n"
    "\t\t\tif ( $eternalParticleFade.x > $eternalParticleFade.y ) {\n"
    "\t\t\t\tfloat epD = length( fragment.texcoord2.xyz - $globalViewOrigin.xyz );\n"
    "\t\t\t\tepCa *= saturate( ( epD - $eternalParticleFade.y ) / ( $eternalParticleFade.x - $eternalParticleFade.y ) );\n"
    "\t\t\t}\n"
    "\t\t\tfloat2 epTc = fragment.position.xy * $renderPositionToViewTexture.zw + $renderPositionToViewTexture.xy;\n"
    "\t\t\tfloat epZs = $projectionMatrixZ.w / ( tex2Dlod( $viewDepthMap, float4( epTc, 0.0, 0.0 ) ).x + $projectionMatrixZ.z );\n"
    "\t\t\tfloat epZf = $projectionMatrixZ.w / ( fragment.position.z + $projectionMatrixZ.z );\n"
    "\t\t\tfloat epSoft = saturate( ( epZs - epZf - saturate( 1.0 - epG ) * $eternalParticle.w ) / max( $eternalParticleFade.z, 1e-3 ) );\n"
    "\n"
    "\t\t\tfloat epM = 1.0;\n"
    "\t\t\tif ( $eternalParticleFade.w != 0.0 ) {\n"
    "\t\t\t\tepM = lerp( tex2D( $eternalParticleEmissiveMap, fragment.texcoord0.xy ).x, tex2D( $eternalParticleEmissiveMap, fragment.texcoord0.zw ).x, epFb );\n"
    "\t\t\t}\n"
    "\n"
    "\t\t\tfloat3 epRgb;\n"
    "\t\t\tfloat epA;\n"
    "\t\t\tfloat epCurve = lerp( sqrt( epG ), epG, epGp3 );\n"
    "\t\t\tif ( epMode == 1.0 ) {\n"
    "\t\t\t\tfloat3 epL;\n"
    "\t\t\t\tEP_BICUBIC( epL, $particlesLightAtlasMap, fragment.texcoord4.xy, $particleAtlasParms.xy );\n"
    "\t\t\t\tepRgb = epR * epC * ( epL + 200.0 * epGp0 ) * $eternalParticleColor2.w;\n"
    "\t\t\t\tif ( $eternalParticle.z != 0.0 ) {\n"
    "\t\t\t\t\tepRgb += $eternalParticleColor.xyz * $eternalParticle.z * epM * epM;\n"
    "\t\t\t\t}\n"
    "\t\t\t\tepA = epCurve * epCa * ( 1.0 + 10.0 * epGp1 );\n"
    "\t\t\t} else if ( epMode == 4.0 ) {\n"
    "\t\t\t\tfloat3 epL;\n"
    "\t\t\t\tEP_BICUBIC( epL, $particlesLightAtlasMap, fragment.texcoord4.xy, $particleAtlasParms.xy );\n"
    "\t\t\t\tepRgb = lerp( epL * epR * epC, lerp( $eternalParticleColor.xyz, $eternalParticleColor2.xyz, epM ) * $eternalParticle.y, epM );\n"
    "\t\t\t\tfloat epO = epCurve * epCa;\n"
    "\t\t\t\tepA = lerp( sqrt( epO ), epO, epGp3 ) * epCa;\n"
    "\t\t\t} else {\n"
    "\t\t\t\tepRgb = epR * epC * ( 1.0 + 200.0 * epGp0 ) * $eternalParticle.y * epCa * epCa;\n"
    "\t\t\t\tepA = epCurve * epCa * ( 1.0 + 10.0 * epGp1 );\n"
    "\t\t\t}\n"
    "\t\t\tepA = saturate( epA * epSoft );\n"
    "\n"
    "\t\t\tfloat3 epHeightFog = lerp( $fogLightInscatterColor.xyz * $fogLightInscatterIntensity.x, $fogLightOppositeColor.xyz, fragment.texcoord6.z );\n"
    "\t\t\tfloat epFogAmount = saturate( fragment.texcoord6.y + fragment.texcoord6.x );\n"
    "\t\t\tfloat epFogSafe = max( epFogAmount, 0.0001 );\n"
    "\t\t\tfloat3 epFogColor = lerp( $fogColor.xyz, epHeightFog, max( 0.0, ( epFogSafe - fragment.texcoord6.x ) / epFogSafe ) );\n"
    "\t\t\tepRgb = lerp( epFogColor * $transparencyLightMult.x, epRgb, 1.0 - epFogAmount );\n"
    "\n"
    "\t\t\tepResult.color = float4( epRgb * epA, epA );\n"
    "\t\t}\n"
    "\t\t#endtemplate\n"
;
